# Independently reclassify exact current expressions as q+c*sqrt(n).
def sqrt(n):
 r=isqrt(n)
 if r*r==n:return(0,F(0),F(r))
 for k in range(r,0,-1):
  if n%(k*k)==0:return(n//(k*k),F(k),F(0))
def shift(v,q):return(v[0],v[1],v[2]+q)
def neg(v):return(v[0],-v[1],-v[2])
def rat(q):return(0,F(0),F(q))
def cl(v):
 n,k,q=v;irr=bool(n and k)
 if irr:
  lo=isqrt(n);assert lo*lo<n<(lo+1)**2
  lower=q+k*(lo if k>0 else lo+1);upper=q+k*(lo+1 if k>0 else lo)
  assert lower>=0 or upper<=0
  sign='positive' if lower>=0 else 'negative'
 else:lower=upper=q;sign='positive' if q>0 else 'negative' if q<0 else 'zero'
 return {'normalForm':{'n':n,'coefficient':str(k),'constant':str(q)},'irrational':irr,'negative':sign=='negative','nonintegerRational':not irr and q.denominator!=1,'integer':not irr and q.denominator==1,'sign':sign,'exactBounds':[str(lower),str(upper)]}
